(function(){var links=[].slice.call(document.querySelectorAll('nav.cats a'));if(!('IntersectionObserver' in window)||!links.length)return;var map={};links.forEach(function(a){map[a.getAttribute('href').slice(1)]=a});var io=new IntersectionObserver(function(es){es.forEach(function(e){if(!e.isIntersecting)return;links.forEach(function(a){a.classList.remove('active');a.removeAttribute('aria-current')});var a=map[e.target.id];if(a){a.classList.add('active');a.setAttribute('aria-current','true');var p=a.parentNode.parentNode;p.scrollTo({left:a.offsetLeft-16,behavior:'smooth'})}});},{rootMargin:'-70px 0px -70% 0px'});document.querySelectorAll('main section').forEach(function(s){io.observe(s)});})();